from __future__ import annotations
import json
from enum import Enum
from typing_extensions import Self


class Format(str, Enum):
    """
    Specifies the types of formats the 'lines' in an observation can be in.  Not all sources can be specified in each format; see above for clarification.  Furthermore, some sources expect slightly different fields in formats.  In particular, the `applog` source expects the entry found in the given format to have a rank-like prefix; for them, the host-specifier field, if present in a format, is optional. `entry_timeseries` is the exception: it parses the prefix only out of an entry that declares no `resources`, and a body timestamp only when `ts` is null (see below).  For `syslog` and `health_check`, the rank-like prefix is not expected, and `host-specifier` fields are mandatory.  Rank-like prefixes are match the following regex: \"^\\[rank\\s*:?\\s*(?P<rank>\\d+)\\]\" or have an integer followed by a colon at the start of the line.  Examples:      [rank3] Message      3: another message     [rank :10] a third message   - `string_list`:      Raw text      Lines of text separated by newlines. No hosts associations.  - `raw_log`:      Raw text      entries separated by newlines. Rank-like prefix expected for applog.  - `raw_loki_streams`:      JSON-based      Top-Level Structure:     - An array of objects, each with:       - `stream`: If host-spcifier needed, *Required*. If present, must contain the `node_name` field (string); which is the host-specifier. All other fields in stream are permitted but ignored.       - `values`: *Required*. An array of entries.      Details:     - `stream` Object. *Required* if host-specifier:       - Required Field:         - `node_name` (string): Identifies the node that generated the logs. Host specifier.         - Other fields: Any other fields within stream are permitted but ignored.     - `values` Array:       - Each entry is a 2-element array:         - Timestamp (string): Unix timestamp; unit scale dictated by Source (see above).         - Entry (string): the main content. Should have rank-line prefix for applog.     - Other fields:       - Any other fields at any level are permitted but ignored.      Example (`syslog` source):     ```json     [       {         \"stream\": {           \"node_name\": \"host-a1b2c3d4\"         },         \"values\": [           [             \"1744734437830498000\",             \"Apr 24 12:04:06 host-a1b2c3d4 kernel: message repeated 8 times: [ NVRM: subdeviceCtrlCmdBusGetNvlinkStatus_IMPL: Failed to collect nvlink status info!]\"           ]         ]       }     ]     ```  - `loki_dict_list`:      JSON-based.      Top-Level Structure:     -  An array of objects, each with:         - `values`: Required. An array of entries.      Details:     - `values` Array:       Each entry is a 2-element array:       - Timestamp (string): Unix timestamp; unit scale dictated by Source (see above).       - Content (string): A JSON-encoded object with at least the following fields:         - `body` (string): entry (required; rank-like prefix expected for APPLOG.)         - `hostname` (string): The source hostname (required if host-specified needed.)     - Other fields:       - The `stream` object is optional and, if present, is ignored.       - Any other fields in the log message JSON are permitted but ignored.      Example (`syslog` source)     ```json     [       {         \"values\": [           [             \"1744734421212766000\",             \"{\\\"body\\\":\\\"Some log message\\\",\\\"hostname\\\":\\\"server-01\\\"}\"           ]         ]       }     ]     ```  - `csv_metric_response`:    Not implemented presently.  - `prometheus_metrics`:    JSON-based.    Top-Level Structure:   - An array of objects, each representing a metric data point.    Details:   - Each object must contain:     - `timestamp` (int): Unix timestamp in seconds     - `value` (Union[int, float, string]): Metric value (initially as string, converted later)     - `metric` (string): Metric name (e.g., \"node_infiniband_link_downed_total\")     - `labels` (dict): Prometheus labels including node and device information     - `node` (string): Node identifier (required, extracted from net_host_name label)     - `component` (string, optional): Component/device identifier (e.g., \"mlx5_0\", \"mlx5_1\")     - `cluster` (string, optional): Cluster identifier (e.g., \"cluster-e5f6g7h8\", extracted from s_cluster label)    Example:   ```json   [     {       \"timestamp\": 1753898040,       \"value\": \"1\",       \"metric\": \"node_infiniband_link_downed_total\",       \"labels\": {         \"net_host_name\": \"host-i9j0k1l2\",         \"s_cluster\": \"cluster-e5f6g7h8\",         \"device\": \"mlx5_0\",         \"instance\": \"host-i9j0k1l2:9100\"       },       \"node\": \"host-i9j0k1l2\",       \"component\": \"mlx5_0\",       \"cluster\": \"cluster-e5f6g7h8\"     }   ]   ```  - `entry_timeseries`:    JSON-based.    Top-Level Structure:   - An array of entry objects.    Details:   - Each entry object contains:     - `body` (string): *Required*. Matched verbatim; nothing is parsed out of it except the       `applog`, `syslog` and `ufmlog` fallbacks described below.     - `ts` (int or null): Unix timestamp in **nanoseconds**, or null/absent when the producer       has no timestamp for this entry. It means \"this entry occurred no later than this time\".       Rounded up to microsecond precision internally, since that is all a `datetime` holds. An       entry without a timestamp is never dropped by time filtering.     - `resources` (optional): What this entry is about. Either the exact string `\"AllJobResources\"`       or an array naming exactly one `{\"kind\": \"node\", \"hostname\": ...}`, optionally alongside       `{\"kind\": \"replica\", \"name\": ...}` objects, which are recorded but not attributed on. Absent,       null and `\"AllJobResources\"` all mean every job resource, so they single out no node. Neither       does an array that fails to name exactly one node the job owns — for example `[]`, several       nodes, replicas with no node (except under `applog`, see below), or a hostname outside the job.       Singling out no node is what decides the entry's fate: a source that requires one drops it, a       source that does not records it against every job resource. Either way the rest of the array is still processed.   - Any other key in an entry is permitted but ignored.    Unlike every other format, entries here are only time-filtered by the observation context's   `time_interval`. That interval is the producer's declared intent: a null bound means unbounded on   that side, so an interval of two nulls disables time filtering for the observation entirely.    Key Source Behavior:   - `applog`:     - `ts` absent or null: the body is parsed for a timestamp. Year-less formats resolve it against       the workload's `job_end_time`.     - `resources` absent, null, or an array naming no node (for example replicas only): the node is       read from the rank-like or node-name text prefix, and declared replicas are kept. A line with       no usable prefix is recorded against every job resource, never dropped. An explicit       `\"AllJobResources\"` skips the prefix parse altogether.   - `syslog`:     - `ts` is the line's timestamp in nanoseconds. An entry without it is dropped, never       parsed out of the body.     - A declared node in `resources` is used as-is, so a host specifier in IP form must be       resolved by the producer. With `resources` absent or null the node is read out of the       syslog line's hostname field instead; a line naming none is dropped.     - `body` is the syslog line as received. The declared interval is what the producer meant       to cover, typically the selected job record plus whatever slack it admits for terminal       events logged just after the record ends.   - `ufmlog`:     - `ts` is the line's timestamp in nanoseconds. An entry without it is kept, never       parsed out of the body, and treated as untimed.     - A declared node in `resources` is used as-is and the body is never parsed. With       `resources` absent or null the job node is read out of the line instead, which names it       either in the link form `(Computer:<node> (<guid>))` or the node form       `(<node>) node is Down`; a line naming neither is dropped     - `body` is the fabric manager log line as received   - `node_metrics` and `nvlink_metrics`:     - `ts` is the sample time in nanoseconds. An entry without it is kept, never       parsed out of the body, and treated as untimed.     - `resources` must name the node the sample is about. An entry that declares no node, or a       node that is not in the job, is dropped.     - `body` is the line `prometheus_metrics` renders from a metric entry, byte for byte    Example:   ```json   [     {       \"ts\": 1744734437830498000,       \"resources\": [{\"kind\": \"node\", \"hostname\": \"host-a1b2c3d4\"}],       \"body\": \"some log message\"     },     {       \"body\": \"a continuation entry the producer could not timestamp\"     }   ]   ```
    """

    """
    allowed enum values
    """
    EMPTY = ''
    STRING_LIST = 'string_list'
    RAW_LOG = 'raw_log'
    RAW_LOKI_STREAMS = 'raw_loki_streams'
    LOKI_DICT_LIST = 'loki_dict_list'
    CSV_METRIC_RESPONSE = 'csv_metric_response'
    UFMLOG = 'ufmlog'
    PROMETHEUS_METRICS = 'prometheus_metrics'
    CSP_EVENT_LIST = 'csp_event_list'
    ENTRY_TIMESERIES = 'entry_timeseries'

    @classmethod
    def from_json(cls, json_str: str) -> Self:
        """Create an instance of Format from a JSON string"""
        return cls(json.loads(json_str))


